import { describe, expect, it } from 'vitest'
import { defaultCalibration } from '../data/calibration'
import { richDemoDataset } from '../data/demoDataset'
import { modelFitVerdict, replayCalibrationRun, replayThermalLog, replayThermalTrace } from './modelFit'
import { analyzeCalibrationRun, stageCalibration } from './thermalLog'
import { thermalStep } from './thermalModel'
import type { CalibrationSettings, ThermalSample } from './types'

/**
 * A log generated BY the thermal model, so the replay has a known-exact answer. This is what proves
 * the harness itself: if the recorded levels really did produce the recorded temperatures under
 * these coefficients, an open-loop replay must land on them.
 */
const modelGeneratedLog = (
  calibration: CalibrationSettings,
  steps: Array<{ fan: number; heat: number; seconds: number }>,
): ThermalSample[] => {
  const ambientC = 22
  const samples: ThermalSample[] = []
  let temperatureC = ambientC
  let rorCPerMin: number | undefined
  let seconds = 0
  samples.push({
    tMs: 0,
    thermocoupleC: temperatureC,
    coldJunctionC: ambientC,
    effectiveFan: steps[0].fan,
    effectiveHeat: steps[0].heat,
  })
  for (const step of steps) {
    // A sampled level describes the interval that starts at that sample. Put the new command on the
    // boundary row so the synthetic fixture matches the replay contract exactly at step changes.
    samples[samples.length - 1].effectiveFan = step.fan
    samples[samples.length - 1].effectiveHeat = step.heat
    for (let second = 0; second < step.seconds; second += 1) {
      const result = thermalStep(
        {
          previousBeanTempC: temperatureC,
          previousRorCPerMin: rorCPerMin,
          fan: step.fan,
          heat: step.heat,
          cooling: step.heat === 0,
          batchMassG: calibration.referenceBatchMassG,
          ambientC,
        },
        calibration,
      )
      temperatureC = result.beanTempC
      rorCPerMin = result.rorCPerMin
      seconds += 1
      samples.push({
        tMs: seconds * 1000,
        thermocoupleC: temperatureC,
        coldJunctionC: ambientC,
        effectiveFan: step.fan,
        effectiveHeat: step.heat,
      })
    }
  }
  return samples
}

describe('replaying a log the model itself produced', () => {
  const steps = [
    { fan: 5, heat: 4, seconds: 200 },
    { fan: 5, heat: 8, seconds: 200 },
    { fan: 9, heat: 8, seconds: 200 },
    { fan: 9, heat: 0, seconds: 200 },
  ]
  const log = modelGeneratedLog(defaultCalibration, steps)

  it('recovers the recorded temperatures almost exactly', () => {
    const fit = replayThermalLog(log, defaultCalibration, { ambientC: 22 })!
    expect(fit.samples).toBeGreaterThan(700)
    expect(fit.rmsC).toBeLessThan(0.5)
    expect(fit.maxC).toBeLessThan(1)
    expect(Math.abs(fit.biasC)).toBeLessThan(0.5)
    expect(fit.seededAtC).toBe(22)
  })

  it('is open loop, so wrong coefficients really do diverge', () => {
    const wrong = { ...defaultCalibration, heaterGainCPerMinAt10: defaultCalibration.heaterGainCPerMinAt10 * 1.5 }
    const fit = replayThermalLog(log, wrong, { ambientC: 22 })!
    expect(fit.rmsC).toBeGreaterThan(20)
    // Too much gain runs hot, and the sign of the bias says which way.
    expect(fit.biasC).toBeGreaterThan(0)
  })

  it('reports where the worst error happened, not just how big it was', () => {
    const wrong = { ...defaultCalibration, thermalLossPerMinPerC: defaultCalibration.thermalLossPerMinPerC * 3 }
    const fit = replayThermalLog(log, wrong, { ambientC: 22 })!
    expect(fit.maxAtSec).toBeGreaterThan(0)
    expect(fit.maxAtSec).toBeLessThanOrEqual(log[log.length - 1].tMs / 1000)
    expect(fit.maxC).toBeGreaterThanOrEqual(fit.rmsC)
  })

  it('returns the complete fitted path while scoring only the requested post-turnaround window', () => {
    const wrong = { ...defaultCalibration, heaterGainCPerMinAt10: defaultCalibration.heaterGainCPerMinAt10 * 1.5 }
    const all = replayThermalTrace(log, wrong, { ambientC: 22 })!
    const tail = replayThermalTrace(log, wrong, { ambientC: 22, scoreFromSec: 600 })!
    expect(tail.samples).toHaveLength(all.samples.length)
    expect(tail.samples.at(-1)?.thermocoupleC).toBe(all.samples.at(-1)?.thermocoupleC)
    expect(tail.fit.samples).toBeLessThan(all.fit.samples)
    expect(tail.fit.maxAtSec).toBeGreaterThanOrEqual(600)
  })

  it('declines a scoring window beyond the recording instead of dividing by zero', () => {
    expect(replayThermalLog(log, defaultCalibration, { ambientC: 22, scoreFromSec: 10_000 })).toBeUndefined()
  })

  it('declines to score a log it cannot read', () => {
    expect(replayThermalLog([], defaultCalibration)).toBeUndefined()
    expect(replayThermalLog([log[0]], defaultCalibration)).toBeUndefined()
    expect(
      replayThermalLog(
        log.map((sample) => ({ ...sample, thermocoupleC: undefined })),
        defaultCalibration,
      ),
    ).toBeUndefined()
  })
})

/**
 * The real passes, and the honest finding.
 *
 * The demo passes were generated from a first-order chamber model whose asymptotes rise steeply
 * with heat even at heat 1. The app's thermal model cannot represent that: its steady state is
 * `ambient + (4 + heating - airflow) / loss`, so the temperature it predicts at heat 1 is pinned
 * near `ambient + 4/loss`, and no positive fan-cooling coefficient can stretch it to match. The
 * residual is therefore large, and it is large for a STRUCTURAL reason rather than a tuning one.
 *
 * That is exactly the thing a user needs to see before trusting a derived plan, and
 * it is the same mismatch that made auto-applying a pass's coefficients the wrong default: a
 * diagnostic pass measures the empty chamber, and the model describes a bean load.
 */
describe('replaying the recorded demo passes', () => {
  const dataset = richDemoDataset()

  it('scores every stored pass without throwing', () => {
    for (const run of dataset.calibrationRuns) {
      const fit = replayCalibrationRun(run, defaultCalibration)!
      expect(fit).toBeDefined()
      expect(Number.isFinite(fit.rmsC)).toBe(true)
      expect(fit.samples).toBeGreaterThan(400)
    }
  })

  it('stays a poor fit however the coefficients are chosen, because the regime is wrong', () => {
    for (const run of dataset.calibrationRuns.filter((candidate) => (candidate.massG ?? 0) === 0)) {
      const derived = { ...defaultCalibration, ...stageCalibration(analyzeCalibrationRun(run)).patch }
      const withEstimate = replayCalibrationRun(run, defaultCalibration)!
      const withDerived = replayCalibrationRun(run, derived)!
      // Both are far outside a usable fit. The estimated bean baseline cannot describe an empty
      // chamber, and neither can the chamber's own derived coefficients once they are read through
      // the bean model's structure - see the module comment in `modelFit.ts`.
      expect(withEstimate.rmsC).toBeGreaterThan(20)
      expect(withDerived.rmsC).toBeGreaterThan(20)
      expect(withDerived.rmsC).toBeLessThan(120)
    }
  })

  it('grades the result in words the reading can be acted on', () => {
    expect(modelFitVerdict(undefined).grade).toBe('unknown')
    expect(modelFitVerdict({ rmsC: 2, maxC: 4, maxAtSec: 1, biasC: 0, samples: 10, seededAtC: 20 }).grade).toBe('good')
    expect(modelFitVerdict({ rmsC: 12, maxC: 20, maxAtSec: 1, biasC: 0, samples: 10, seededAtC: 20 }).grade).toBe(
      'fair',
    )
    expect(modelFitVerdict({ rmsC: 60, maxC: 90, maxAtSec: 1, biasC: 0, samples: 10, seededAtC: 20 }).grade).toBe(
      'poor',
    )
    for (const run of dataset.calibrationRuns.filter((candidate) => (candidate.massG ?? 0) === 0)) {
      expect(modelFitVerdict(replayCalibrationRun(run, defaultCalibration)).grade).toBe('poor')
    }
  })
})
